// LOCAL check of the restore SQL generated by scripts/restore-from-backup.ps1 (PGlite; NOT Supabase).
// 1. powershell -File scripts\test-backup-lib.ps1 -FixtureDir <dir>      (builds a backup + restore SQL from a fake DB)
// 2. cd database\tests; npm i --no-save @electric-sql/pglite; node restore-sql-check.mjs <dir>
import { PGlite } from '@electric-sql/pglite';
import { readFileSync, readdirSync } from 'node:fs';
import { execSync } from 'node:child_process';

const fixture = process.argv[2];
if (!fixture) throw new Error('usage: node restore-sql-check.mjs <fixture dir>');
const repo = new URL('../../', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1');
const backupDir = readFileSync(`${fixture}/backup-path.txt`, 'utf8').trim();
const expected = JSON.parse(readFileSync(`${fixture}/expected.json`, 'utf8'));
const sqlDir = `${backupDir}/restore-sql`;
const files = readdirSync(sqlDir).sort();
const sql = Object.fromEntries(files.map(f => [f.replace(/^\d+-|\.sql$/g, ''), readFileSync(`${sqlDir}/${f}`, 'utf8')]));
// The ORIGINAL production schema, pinned (commit ed23a6f). Do not use git HEAD: HEAD now contains the two-role setup SQL.
const oldSetup = readFileSync(repo + 'database/tests/fixtures/supabase_setup.pre-two-role.sql', 'utf8');
const migration = readFileSync(`${repo}database/migrations/2026-11-23-two-role-user-management.sql`, 'utf8');
const rollback = readFileSync(`${repo}database/migrations/2026-11-23-two-role-user-management.rollback.sql`, 'utf8');

const bootstrap = `
CREATE ROLE anon NOLOGIN; CREATE ROLE authenticated NOLOGIN; CREATE ROLE service_role NOLOGIN BYPASSRLS;
CREATE SCHEMA auth;
CREATE TABLE auth.users (id uuid PRIMARY KEY, email text, encrypted_password text, created_at timestamptz DEFAULT now(), last_sign_in_at timestamptz);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;
GRANT USAGE ON SCHEMA public, auth TO anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT EXECUTE ON FUNCTIONS TO anon, authenticated, service_role;`;

let pass = 0, fail = 0;
const ok = (n, c, d = '') => { c ? pass++ : fail++; console.log(`${c ? 'PASS' : 'FAIL'}  ${n}${d ? '  -> ' + d : ''}`); };
const num = v => (v == null ? null : Number(v));
const ts = v => (v == null ? null : new Date(v).getTime());

// ---- Scenario 1: total loss of the three business tables + profiles on the live (old) schema
const db = new PGlite();
await db.exec(bootstrap); await db.exec(oldSetup);
await db.exec(`TRUNCATE public.user_profiles, public.snack_records, public.employees, public.snacks RESTART IDENTITY CASCADE;`);
for (const p of expected.user_profiles) await db.query('INSERT INTO auth.users (id, email) VALUES ($1, $2) ON CONFLICT DO NOTHING', [p.user_id, p.user_id + '@x.test']);
ok('simulated disaster: all four tables empty', (await db.query('select (select count(*) from public.employees)+(select count(*) from public.snacks)+(select count(*) from public.snack_records)+(select count(*) from public.user_profiles) n')).rows[0].n === 0);

for (const t of ['employees', 'snacks', 'snack_records']) await db.exec(sql[t]);
const E = (await db.query('select * from public.employees order by id')).rows;
ok('employees restored exactly (ids, names incl. quotes/unicode/newline/$bk0$, flags)', E.length === expected.employees.length && E.every((r, i) => Number(r.id) === expected.employees[i].id && r.name === expected.employees[i].name && r.active === expected.employees[i].active), `${E.length}`);
const S = (await db.query('select * from public.snacks order by id')).rows;
ok('snacks restored exactly (ids, names, prices)', S.length === expected.snacks.length && S.every((r, i) => Number(r.id) === expected.snacks[i].id && r.name === expected.snacks[i].name && num(r.unit_price) === num(expected.snacks[i].unit_price)));
const R = (await db.query('select * from public.snack_records order by id')).rows;
ok(`snack_records restored exactly (${expected.snack_records.length} rows: ids, FKs, break types, prices, timestamps)`, R.length === expected.snack_records.length && R.every((r, i) => { const e = expected.snack_records[i]; return Number(r.id) === e.id && Number(r.employee_id) === e.employee_id && Number(r.snack_id) === e.snack_id && r.quantity === e.quantity && (r.break_type ?? null) === (e.break_type ?? null) && num(r.unit_price) === num(e.unit_price) && ts(r.taken_at) === ts(e.taken_at); }), `${R.length}`);
const seq = await db.query(`insert into public.employees (name) values ('After Restore') returning id`);
ok('identity sequence advanced (a new employee gets an id above the restored max)', Number(seq.rows[0].id) > 3, String(seq.rows[0].id));
await db.exec(sql.user_profiles);
const P = (await db.query('select user_id, role, employee_id from public.user_profiles order by user_id')).rows;
const expP = [...expected.user_profiles].sort((a, b) => a.user_id.localeCompare(b.user_id));
ok('user_profiles restored (user ids, roles, employee links)', P.length === expP.length && P.every((r, i) => r.user_id === expP[i].user_id && r.role === expP[i].role && num(r.employee_id) === num(expP[i].employee_id)));

// ---- Scenario 2: restore must NOT touch rows that still exist
const db2 = new PGlite();
await db2.exec(bootstrap); await db2.exec(oldSetup);
await db2.exec(`TRUNCATE public.user_profiles, public.snack_records, public.employees, public.snacks RESTART IDENTITY CASCADE;`);
await db2.exec(`INSERT INTO public.employees (id, name) OVERRIDING SYSTEM VALUE VALUES (1, 'Changed Since Backup');`);
await db2.exec(sql.employees);
const kept = (await db2.query('select name from public.employees where id = 1')).rows[0].name;
const cnt = (await db2.query('select count(*)::int n from public.employees')).rows[0].n;
ok('existing row is never overwritten by the restore (ON CONFLICT DO NOTHING)', kept === 'Changed Since Backup', kept);
ok('only the missing employees were re-created', cnt === expected.employees.length, String(cnt));
await db2.exec(sql.employees);
ok('running the restore twice is harmless (idempotent)', (await db2.query('select count(*)::int n from public.employees')).rows[0].n === expected.employees.length);

// ---- Scenario 3: profile restore after the migration must demand the rollback first
const db3 = new PGlite();
await db3.exec(bootstrap); await db3.exec(oldSetup);
await db3.exec(`TRUNCATE public.user_profiles, public.snack_records, public.employees, public.snacks RESTART IDENTITY CASCADE;`);
for (const p of expected.user_profiles) await db3.query('INSERT INTO auth.users (id, email) VALUES ($1, $2) ON CONFLICT DO NOTHING', [p.user_id, p.user_id + '@x.test']);
await db3.exec(sql.employees);
await db3.exec(`INSERT INTO public.user_profiles (user_id, role, employee_id) VALUES ('00000000-0000-0000-0000-0000000000aa','admin',NULL)`);
await db3.exec(migration);
let msg = null; try { await db3.exec(sql.user_profiles); } catch (e) { msg = e.message; await db3.exec('ROLLBACK'); /* the aborted transaction is discarded, as when a real session ends */ }
ok('profile restore refuses to run on the migrated schema (tells you to roll back first)', /rollback/i.test(msg || ''), msg);
const adminStill = (await db3.query(`select count(*)::int n from public.user_profiles where role='admin'`)).rows[0].n;
ok('refused restore changed nothing (transaction rolled back)', adminStill === 1);
await db3.exec(rollback); await db3.exec(sql.user_profiles);
const roles = (await db3.query(`select role, count(*)::int n from public.user_profiles group by role order by role`)).rows;
ok("after rollback the original profiles ('admin' / 'employee') are restored", JSON.stringify(roles) === JSON.stringify([{ role: 'admin', n: 1 }, { role: 'employee', n: 2 }]), JSON.stringify(roles));

console.log(`\n${pass} passed, ${fail} failed (local PGlite; NOT Supabase)`);
process.exit(fail ? 1 : 0);
